function ageValues(value) {
  if (!value || value === 'Not stated') return [];
  if (value === '8U-14U') return ['8U','10U','12U','14U'];
  return [value];
}

export const CURATED_SEED_DRILLS = RAW.trim().split('\n').map((line, index) => {
  const [drillId,title,skillText,sourceType,ageRange,difficulty,participationMode,summary] = line.split('|');
  const skills = skillText.split('/').map(value => value.trim()).filter(Boolean);
  const base = {
    id: 1001 + index,
    drillId,
    title,
    resourceType: 'Drill',
    status: 'Approved',
    folder: 'Unfiled',
    sourceType,
    summary,
    teachingMethod: participationMode,
    participationMode,
    primarySkill: { name: skills[0] || 'General', weight: 90, reason: 'Curated primary skill.' },
    supportingSkills: skills.slice(1).map(name => ({ name, weight: 55 })),
    setup: { players: 'Not stated', equipment: [], space: 'Not stated', age: ageValues(ageRange) },
    difficulty,
    ageRange,
    sourceUrl: '',
    sourceVerified: false,
    libraryShell: true,
    updated: 'CoachVault Library v1'
  };
  return { ...base, ...(SOURCE_BACKED_OVERRIDES[drillId] || {}) };
});
